#!/usr/bin/env node
// PROP-149 Part A (ISS-3025a): citation-parity audit for hardcoded-monitoring WINs.
// Flags (1) WINs in the hardcoded-monitoring scope with NO dome-artifact citation
// (raw-text/NN-*.txt, monitor.py, claim_index.json, status_history.json), and
// (2) WINs carrying hedge phrases (the ISS-2861 'appear to be' class) even when
// a citation exists. Exit 0 = parity clean, 3 = flagged entries (print to stdout),
// 2 = internal error (never report clean on error).
const fs = require('fs');
try {
  const wins = JSON.parse(fs.readFileSync('data/wins.json', 'utf8'));
  const HEDGES = [/appear(s)? to be/i, /seem(s)? to/i, /no independent code audit/i, /likely (static|hardcoded)/i, /presumably/i];
  const CITES = [/raw-text\/\d{2}-[\w-]+\.txt/i, /monitor\.py/i, /claim_index\.json/i, /status_history\.json/i];
  const inScope = wins.filter(w => /hardcod|static constant/i.test(JSON.stringify(w)));
  const results = [];
  for (const w of inScope) {
    const text = [w.detail_verdict_text, w.detail_evidence, w.verdict_text, w.evidence].filter(Boolean).join('\n');
    const hedges = HEDGES.filter(h => h.test(text)).map(String);
    const hasCite = CITES.some(c => c.test(text));
    results.push({ id: w.id, has_artifact_citation: hasCite, hedge_phrases: hedges, parity_ok: hasCite && hedges.length === 0 });
  }
  const flagged = results.filter(r => !r.parity_ok);
  console.log(JSON.stringify({ event: 'citation-parity-audit', generated_at: new Date().toISOString(), in_scope: results.length, flagged: flagged.length, flagged_ids: flagged.map(f => f.id), results }, null, 2));
  process.exit(flagged.length ? 3 : 0);
} catch (e) {
  console.error('citation-parity-audit ERROR: ' + e.message);
  process.exit(2);
}

