// PROP-149 (ISS-3025b): count consecutive PRIOR review cycles for the same
// base item whose advocate_mode.defense_survives was already >= 3. Walks
// c(N-1), c(N-2), ... base directly from REVIEWS_DIR; stops at the first
// cycle below threshold or with no review file. Returns 0 when the current
// review itself is below threshold.
function countRecurrentDefenseCycles(baseId, review) {
  if (!(review.advocate_mode && review.advocate_mode.defense_survives >= 3)) return 0;
  const current = review.cycle || 1;
  let count = 0;
  for (let c = current - 1; c >= 1; c--) {
    const fname = c === 1 ? `${baseId}.json` : `${baseId}.c${c}.json`;
    const prior = loadJSON(path.join(REVIEWS_DIR, fname));
    if (!prior || !prior.advocate_mode || !(prior.advocate_mode.defense_survives >= 3)) break;
    count++;
  }
  return count;
}

